    PaynotesUi(MainActivity a){this.a=a;this.coach=new CoachUi(this);try{font=a.getResources().getFont(R.font.dm_sans);}catch(Exception e){font=Typeface.create("sans-serif",Typeface.NORMAL);}}
    int dp(float n){return (int)(n*a.getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
