    void save(Bundle state){state.putString("pn.mode",mode);state.putString("pn.anchor",anchor.toString());state.putString("pn.type",type);state.putString("pn.query",query);state.putString("pn.category",category);state.putString("pn.range",rangeLabel);state.putLong("pn.from",from);state.putLong("pn.until",until);state.putString("pn.draft",draft);if(account!=null){state.putString("pn.issuer",account.issuer());state.putString("pn.mask",account.mask());}}
