    void insights(){
        if(content==null)return;LinearLayout layout=column();layout.setPadding(dp(24),dp(12),dp(24),dp(12));content.removeAllViews();content.addView(layout);a.page=layout;
        layout.addView(text("Insights",28,INK,true));note(layout,"Understand your spending. Make room for what matters.");
        LinearLayout coaching=row();chipAdd(coaching,chip("My plan",false,coach::hub));chipAdd(coaching,chip("Goal",false,coach::goal));chipAdd(coaching,chip("Limits",false,coach::limits));layout.addView(coaching);
        LinearLayout toolbar=row();boolean connected=!Store.prefs(a).getString("ai_endpoint","").isEmpty();TextView status=text(connected?"AI connection configured":"Local summaries · AI not connected",12,TEAL,true);toolbar.addView(status,new LinearLayout.LayoutParams(0,-2,1));TextView options=text("•••",20,INK,true);options.setPadding(dp(12),dp(10),dp(12),dp(10));options.setMinHeight(dp(48));options.setContentDescription("Conversation options");options.setOnClickListener(v->new AlertDialog.Builder(a).setItems(new String[]{"AI connection","Clear conversation"},(d,w)->{if(w==0)a.configureAi();else new AlertDialog.Builder(a).setTitle("Clear this conversation?").setMessage("Removes this chat from this phone. It does not delete previously sent AI data.").setPositiveButton("Clear",(x,y)->{Store.prefs(a).edit().remove("paynotes_chat").putLong("chat_revision",Store.prefs(a).getLong("chat_revision",0)+1).apply();render();}).setNegativeButton("Cancel",null).show();}).show());toolbar.addView(options);layout.addView(toolbar);
        ScrollView conversation=new ScrollView(a);conversation.setVerticalScrollBarEnabled(false);LinearLayout messages=column();conversation.addView(messages);layout.addView(conversation,new LinearLayout.LayoutParams(-1,0,1));
        JSONArray history=history();
        if(history.length()==0){gap(messages,24);messages.addView(text("What would you like\nto understand?",30,INK,true));gap(messages,12);messages.addView(text("Understand your spending, build a payday plan or make progress toward a goal.",16,MUTED,false));gap(messages,24);for(String prompt:new String[]{"How does this month compare?","Where did my money go?","Help me plan until payday"}){messages.addView(action(prompt,false,()->ask(prompt)));gap(messages,10);}note(messages,"Local answers use recorded payments. Connect AI in Settings for an open-ended conversation.");}
        else {for(int i=0;i<history.length();i++){JSONObject message=history.optJSONObject(i);boolean user=message.optString("role").equals("user");LinearLayout bubble=column();bubble.setPadding(dp(16),dp(14),dp(16),dp(14));bubble.setBackground(bg(user?TEAL:0xffffffff,16));bubble.addView(text(user?"YOU":message.optString("engine","PAYNOTES"),11,user?0xffddf4f5:TEAL,true));gap(bubble,6);bubble.addView(text(message.optString("content"),16,user?0xffffffff:INK,false));if(!user){bubble.addView(action("Listen / stop",false,()->speak(message.optString("content"))));JSONObject proposal=message.optJSONObject("proposal");if(proposal!=null)bubble.addView(action("Review suggested "+proposal.optString("type"),false,()->{try{CoachProposal.validate(proposal);if(proposal.optString("type").equals("goal"))coach.goal(proposal);else coach.limits(proposal);}catch(Exception e){Toast.makeText(a,"This suggestion is no longer valid. Create a new plan or goal.",Toast.LENGTH_LONG).show();}}));}LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(12);if(user)bp.setMarginStart(dp(28));else bp.setMarginEnd(dp(8));messages.addView(bubble,bp);}gap(messages,12);messages.addView(action("Review plan, goals & limits",false,coach::hub));}
        if(CHAT_BUSY.get())note(messages,"Thinking about your question…");
        LinearLayout compose=row();compose.setPadding(0,dp(12),0,0);EditText input=field("Message to Paynotes","Ask about your spending…",draft);input.setMaxLines(3);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(1200)});compose.addView(action("Talk",false,this::voice),new LinearLayout.LayoutParams(-2,-2));compose.addView(input,new LinearLayout.LayoutParams(0,-2,1));input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int c){draft=s.toString();}public void afterTextChanged(Editable e){}});TextView send=action("↑",true,()->{String question=input.getText().toString().trim();if(!question.isEmpty())ask(question);});send.setTextSize(24);send.setContentDescription("Send message");send.setEnabled(!CHAT_BUSY.get());LinearLayout.LayoutParams sendParams=new LinearLayout.LayoutParams(dp(52),dp(52));sendParams.setMarginStart(dp(8));compose.addView(send,sendParams);layout.addView(compose);if(history.length()>0)conversation.post(()->conversation.fullScroll(View.FOCUS_DOWN));
    }
    private JSONArray history(){try{return new JSONArray(Store.prefs(a).getString("paynotes_chat","[]"));}catch(JSONException e){return new JSONArray();}}
    private void append(String role,String content,String engine){append(role,content,engine,null);}
    private void append(String role,String content,String engine,JSONObject proposal){try{JSONArray old=history(),next=new JSONArray();for(int i=Math.max(0,old.length()-19);i<old.length();i++)next.put(old.getJSONObject(i));next.put(new JSONObject().put("role",role).put("content",content).put("engine",engine).put("proposal",proposal));Store.prefs(a).edit().putString("paynotes_chat",next.toString()).apply();}catch(JSONException e){throw new IllegalStateException(e);}}
    private void ask(String question){
        if(CHAT_BUSY.get())return;int request=ticket;long generation=Store.prefs(a).getLong("generation",0);READS.execute(()->{try{PaynotesData.Overview month=PaynotesData.overview(LedgerDb.get(a),"Month",LocalDate.now(),ZonedDateTime.now());String local=CoachAnswers.answer(question,month,CoachStore.snapshot(LedgerDb.get(a),LocalDate.now()));String endpoint=Store.prefs(a).getString("ai_endpoint","");if(endpoint.isEmpty()){a.runOnUiThread(()->{if(!current(request)||generation!=Store.prefs(a).getLong("generation",0))return;append("user",question,"");append("assistant",local,"LOCAL SUMMARY");draft="";render();});return;}
            JSONArray context=new JSONArray();JSONArray old=history();int first=old.length(),characters=question.length();while(first>0&&old.length()-first<10&&characters+old.optJSONObject(first-1).optString("content").length()<=14000){characters+=old.optJSONObject(--first).optString("content").length();}for(int i=first;i<old.length();i++){JSONObject m=old.getJSONObject(i);context.put(new JSONObject().put("role",m.optString("role")).put("content",m.optString("content")));}context.put(new JSONObject().put("role","user").put("content",question));JSONObject payload=new JSONObject().put("messages",context).put("facts",PaynotesData.chatFacts(month,Store.prefs(a).getString("period","Monthly").equals("Monthly")?Store.prefs(a).getLong("budget",0):0));payload.getJSONObject("facts").put("coaching",CoachStore.facts(CoachStore.snapshot(LedgerDb.get(a),LocalDate.now())));
            a.runOnUiThread(()->{if(!current(request)||generation!=Store.prefs(a).getLong("generation",0))return;TextView preview=text("Your conversation, entered plan, goal name, spending preferences and these totals will go to your configured server, then OpenAI. Text you type may contain personal details. Raw messages, payees, accounts and references are not automatically attached.\n\nDestination: "+endpoint+"\n\n"+payload.toString(),14,INK,false);preview.setPadding(dp(24),dp(12),dp(24),dp(12));ScrollView box=new ScrollView(a);box.addView(preview);new AlertDialog.Builder(a).setTitle("Send to AI?").setView(box).setPositiveButton("Send",(d,w)->sendChat(endpoint,payload,question,generation)).setNegativeButton("Keep local",(d,w)->{append("user",question,"");append("assistant",local,"LOCAL SUMMARY");draft="";render();}).show();});
        }catch(Exception e){a.runOnUiThread(()->Toast.makeText(a,"Couldn't prepare your question. Try again.",Toast.LENGTH_LONG).show());}});
    }
    private void sendChat(String endpoint,JSONObject payload,String question,long generation){if(generation!=Store.prefs(a).getLong("generation",0))return;if(!CHAT_BUSY.compareAndSet(false,true))return;append("user",question,"");draft="";render();long revision=Store.prefs(a).getLong("chat_revision",0);NETWORK.execute(()->{String answer,engine;JSONObject proposal=null;try{JSONObject result=AiClient.chatResponse(endpoint,SecureConfig.token(a),payload);answer=result.getString("reply");proposal=result.optJSONObject("proposal");engine="PAYNOTES AI";}catch(Exception e){try{answer="The AI service is unavailable. No plan changes were made. Here is an offline answer:\n\n"+CoachAnswers.answer(question,PaynotesData.overview(LedgerDb.get(a),"Month",LocalDate.now(),ZonedDateTime.now()),CoachStore.snapshot(LedgerDb.get(a),LocalDate.now()));}catch(Exception unavailable){answer="The AI service is unavailable. Your records are unchanged. Try again or review your plan locally.";}engine="OFFLINE FALLBACK";}String reply=answer,label=engine;JSONObject suggestion=proposal;a.runOnUiThread(()->{CHAT_BUSY.set(false);if(generation!=Store.prefs(a).getLong("generation",0)||revision!=Store.prefs(a).getLong("chat_revision",0)){if(!a.isDestroyed()&&a.tab.equals("Insights"))render();return;}append("assistant",reply,label,suggestion);if(!a.isDestroyed()&&a.tab.equals("Insights"))render();});});}
    void voice(){
        new AlertDialog.Builder(a).setTitle("Speak to Paynotes").setMessage("Your device's speech service will transcribe your voice and may process audio online. Review and edit the text before sending. Paynotes does not store audio.").setPositiveButton("Start speaking",(d,w)->{try{a.startActivityForResult(new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(android.speech.RecognizerIntent.EXTRA_PREFER_OFFLINE,true).putExtra(android.speech.RecognizerIntent.EXTRA_PROMPT,"Tell Paynotes what's on your mind"),731);}catch(ActivityNotFoundException e){Toast.makeText(a,"No speech service available. You can still type your message.",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancel",null).show();
    }
    void voiceResult(Intent data){if(data==null)return;ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){draft=words.get(0).substring(0,Math.min(1200,words.get(0).length()));a.tab="Insights";render();Toast.makeText(a,"Review the transcript, then tap Send.",Toast.LENGTH_LONG).show();}}
    void speak(String reply){
        if(speech!=null&&speech.isSpeaking()){speech.stop();return;}
        if(speech==null){speech=new android.speech.tts.TextToSpeech(a,status->{speechReady=status==android.speech.tts.TextToSpeech.SUCCESS;if(speechReady&&!a.isDestroyed()&&a.hasWindowFocus())a.runOnUiThread(()->speak(reply));else Toast.makeText(a,"Speech playback unavailable. The answer is still readable.",Toast.LENGTH_LONG).show();});return;}
        if(speechReady){var voices=speech.getVoices();android.speech.tts.Voice local=null;if(voices!=null)for(var v:voices)if(!v.isNetworkConnectionRequired()&&v.getLocale().getLanguage().equals("en")){local=v;break;}if(local==null){Toast.makeText(a,"Install an offline English voice in device speech settings to listen privately.",Toast.LENGTH_LONG).show();return;}speech.setVoice(local);speech.speak(reply.substring(0,Math.min(reply.length(),android.speech.tts.TextToSpeech.getMaxSpeechInputLength())),android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"paynotes-reply");}
    }
    void stopSpeech(){if(speech!=null)speech.stop();}
    void close(){if(speech!=null){speech.shutdown();speech=null;}}
