        gap(box,20);TextView importButton=action(a.importBusy?"Importing messages…":"Import bank messages",true,()->{if(!a.importBusy)connectSms(true);});importButton.setEnabled(!a.importBusy);box.addView(importButton);
        note(box,"Last 90 days · existing entries are kept");TextView range=action("Choose import range",false,()->new AlertDialog.Builder(a).setTitle("Import history").setItems(new String[]{"Last 90 days","All received history"},(d,w)->{a.importDays=w==0?90:0;connectSms(true,false);}).show());box.addView(range);
        String status=Store.prefs(a).getString("import_summary",a.importStatus);if(!status.isEmpty())note(box,status);if(Store.prefs(a).getBoolean("capture_error",false))note(box,"Some captures failed. Re-import available messages to recover them.");
